use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// Mirrors the `with HTTPClient<[...]>` allowlist of this node. The host also
/// enforces it; checking here means an out-of-scope URL is recorded as a
/// failure instead of trapping the whole run.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

struct Node;

/// Extracts the authority of an `https://` URL. Returns `None` for anything
/// that is not a bare host: other schemes, userinfo (`@`), explicit ports (`:`),
/// IPv6 literals, backslashes, or whitespace.
fn https_host(url: &str) -> Option<&str> {
    let rest = url.strip_prefix("https://")?;
    let end = rest
        .find(|c| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..end];
    if authority.is_empty()
        || authority.contains(['@', ':', '[', ']', '\\'])
        || authority.chars().any(char::is_whitespace)
    {
        return None;
    }
    Some(authority)
}

/// Exact host match against the allowlist. Subdomains are not included.
fn is_allowed(url: &str) -> bool {
    match https_host(url) {
        Some(host) => ALLOWED_HOSTS
            .iter()
            .any(|allowed| host.eq_ignore_ascii_case(allowed)),
        None => false,
    }
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls {
            if !is_allowed(&url) {
                failures.push(FetchFailure {
                    url,
                    error: "url is outside this node's host allowlist".to_string(),
                });
                continue;
            }

            // `fetch` returns transport failures as values, so one dead feed
            // does not fail the tick. An out-of-scope host would still trap at
            // the boundary, which is why it is filtered above.
            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
